		pad := theme.AppBackgroundStyle.Render(strings.Repeat(" ", padLen))
		result = append(result,
			theme.ShortcutKeyStyle.Render(key)+pad+
				theme.ShortcutDescriptionStyle.Render(shortcut.Description))
	}
	return result
}
