		enabled  []string
		disabled []string
	}{
		{
			name: "scanned git repo", cursor: 0, scanned: true,
			enabled: []string{"enter", keymap.Web, keymap.Scan, keymap.Fetch, keymap.Copy},
		},
		{
			name: "unscanned git repo", cursor: 1,
