			name: "a file", cursor: 4,
			enabled:  []string{"enter", keymap.Copy},
			disabled: []string{keymap.Web, keymap.Scan, keymap.Fetch},
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
