			if tc.scanned {
				m = scannedModel(t)
			}
			m.table.SetCursor(tc.cursor)

			got := m.GetShortcuts()
			for _, key := range append(tc.enabled, tc.disabled...) {
				if !hasShortcut(got, key) {
